void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Assuming resultMap contains "leftPartitionSize" and "rightPartitionSize"
    int leftPartitionSize = Integer.parseInt(resultMap.get("leftPartitionSize").toString());
    int rightPartitionSize = Integer.parseInt(resultMap.get("rightPartitionSize").toString());

    // Create vertices for the left partition
    List<V> leftVertices = new ArrayList<>();
    for (int i = 0; i < leftPartitionSize; i++) {
        V vertex = target.addVertex();
        leftVertices.add(vertex);
    }

    // Create vertices for the right partition
    List<V> rightVertices = new ArrayList<>();
    for (int i = 0; i < rightPartitionSize; i++) {
        V vertex = target.addVertex();
        rightVertices.add(vertex);
    }

    // Connect every vertex in the left partition to every vertex in the right partition
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

