static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Calculate the start day of the month
    int startDay = 1;

    // Adjust the dayOfMonth to the new time bucket
    int adjustedDay = ((dayOfMonth - startDay) / dayStep) * dayStep + startDay;

    // Handle the case where the adjusted day is beyond the current month
    if (adjustedDay < dayOfMonth) {
        adjustedDay += dayStep;
    }

    // Ensure the adjusted day does not exceed the number of days in the month
    int daysInMonth = getDaysInMonth(year, month);
    if (adjustedDay > daysInMonth) {
        adjustedDay = daysInMonth;
    }

    return year * 10000 + month * 100 + adjustedDay;
}

static int getDaysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) ? 29 : 28;
        default:
            return 0; // Invalid month
    }
}

long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Calculate the first day of the current month
    long firstDayOfMonth = year * 10000 + month * 100 + 1;

    // Calculate the offset of the current day from the first day of the month
    int dayOffset = dayOfMonth - 1;

    // Calculate the new day of the month by stepping back to the nearest dayStep day
    int newDayOfMonth = ((dayOffset / dayStep) * dayStep) + 1;

    // Combine the year, month, and new day of the month to form the compressed time bucket
    return year * 10000 + month * 100 + newDayOfMonth;
}

int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i++; // Skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

