    int size = 0;
    final int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < end) {
                char nextC = str.charAt(i + 1);
                if (Character.isSurrogatePair(c, nextC)) {
                    size += 4;
                    i++; // Skip the next character as it is part of the surrogate pair
                } else {
                    size += 3; // Invalid surrogate pair, treat as two separate characters
                }
            } else {
                size += 3; // Trailing surrogate, treat as separate character
            }
        } else {
            size += 3;
        }
    }
    return size;
}

