String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    int len = str.length();
    while (i < len) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            i++;
            if (i >= len) {
                throw new Exception("Invalid escape sequence");
            }
            ch = str.charAt(i);
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int unicode = Integer.parseInt(hex, 16);
                        sb.append((char) unicode);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
