protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = edgeList.isEmpty() ? null : graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    if (startVertex != null) {
        vertexList.add(startVertex);
        V currentVertex = startVertex;
        while (!edgeList.isEmpty()) {
            for (E edge : edgeList) {
                if (graph.getEdgeSource(edge).equals(currentVertex)) {
                    currentVertex = graph.getEdgeTarget(edge);
                    vertexList.add(currentVertex);
                    edgeList.remove(edge);
                    break;
                } else if (graph.getEdgeTarget(edge).equals(currentVertex)) {
                    currentVertex = graph.getEdgeSource(edge);
                    vertexList.add(currentVertex);
                    edgeList.remove(edge);
                    break;
                }
            }
        }
    }
    return new GraphPathImpl<>(graph, startVertex, currentVertex, vertexList, tour, 0.0);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertexList = new ArrayList<>();
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0);
    }
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    vertexList.add(startVertex);
    V currentVertex = graph.getEdgeTarget(startEdge);
    tour.remove(startEdge);

    while (!tour.isEmpty()) {
        vertexList.add(currentVertex);
        E nextEdge = null;
        for (E edge : tour) {
            if (graph.getEdgeSource(edge).equals(currentVertex)) {
                nextEdge = edge;
                currentVertex = graph.getEdgeTarget(edge);
                break;
            } else if (graph.getEdgeTarget(edge).equals(currentVertex)) {
                nextEdge = edge;
                currentVertex = graph.getEdgeSource(edge);
                break;
            }
        }
        if (nextEdge != null) {
            tour.remove(nextEdge);
        } else {
            break; // should not happen if the set forms a valid tour
        }
    }
    vertexList.add(vertexList.get(0)); // complete the tour
    return new GraphPathImpl<>(graph, null, vertexList, 0);
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = edgeList.isEmpty() ? null : graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    V currentVertex = startVertex;
    while (currentVertex != null) {
        vertexList.add(currentVertex);
        E nextEdge = null;
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge != null) {
            visitedEdges.add(nextEdge);
            currentVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        } else {
            currentVertex = null;
        }
    }

    return graph.getPath(vertexList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0.0);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(startVertex);

    for (E edge : edgeList) {
        V targetVertex = graph.getEdgeTarget(edge);
        vertexList.add(targetVertex);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, graph.getType().isDirected() ? calculateDirectedPathWeight(edgeList, graph) : calculateUndirectedPathWeight(edgeList, graph));
}

private double calculateDirectedPathWeight(List<E> edgeList, Graph<V,E> graph) {
    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }
    return weight;
}

private double calculateUndirectedPathWeight(List<E> edgeList, Graph<V,E> graph) {
    double weight = 0.0;
    Set<E> visitedEdges = new HashSet<>();
    for (E edge : edgeList) {
        if (!visitedEdges.contains(edge)) {
            weight += graph.getEdgeWeight(edge);
            visitedEdges.add(edge);
            visitedEdges.add(graph.getEdge(graph.getEdgeTarget(edge), graph.getEdgeSource(edge)));
        }
    }
    return weight;
}

