    // Assuming K can be compared, e.g., K implements Comparable<K>
    List<Integer> upperBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return upperBounds;
    }

    // Sort the keys first to find upper bounds
    keys.sort(Comparator.naturalOrder());

    for (int i = 0; i < keys.size(); i++) {
        // For the last key, the upper bound is not defined in the list, so we use Integer.MAX_VALUE
        int upperBound = (i < keys.size() - 1) ? (Integer) keys.get(i + 1) - 1 : Integer.MAX_VALUE;
        upperBounds.add(upperBound);
    }

    return upperBounds;
}

