String applyRelativePath(String path, String relativePath) {
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");

    int i = 0;
    while (i < relativeParts.length && relativeParts[i].equals("..")) {
        if (pathParts.length > 1) {
            pathParts = Arrays.copyOfRange(pathParts, 0, pathParts.length - 1);
        }
        i++;
    }

    StringBuilder result = new StringBuilder();
    for (String part : pathParts) {
        if (!part.isEmpty()) {
            if (result.length() > 0) {
                result.append("/");
            }
            result.append(part);
        }
    }

    for (; i < relativeParts.length; i++) {
        if (!relativeParts[i].isEmpty() && !relativeParts[i].equals(".")) {
            if (result.length() > 0) {
                result.append("/");
            }
            result.append(relativeParts[i]);
        }
    }

    return result.toString();
}

String function ( String path , String relativePath ) { 
    // Split the path into components
    String[] pathComponents = path.split("/") ;
    // Split the relative path into components
    String[] relativePathComponents = relativePath.split("/") ;

    // Use a stack to process the path components
    Stack<String> stack = new Stack<>() ;
    for (String component : pathComponents) {
        if (!component.isEmpty()) {
            stack.push(component);
        }
    }

    // Process the relative path components
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!component.isEmpty() && !component.equals(".")) {
            stack.push(component);
        }
    }

    // Join the stack back into a path
    StringBuilder resultPath = new StringBuilder();
    for (String component : stack) {
        if (resultPath.length() > 0) {
            resultPath.append("/");
        }
        resultPath.append(component);
    }

    // If the original path started with a "/", ensure the result does too
    if (path.startsWith("/") && resultPath.length() > 0 && !resultPath.toString().startsWith("/")) {
        resultPath.insert(0, "/");
    }

    return resultPath.toString();
}

